import{_ as a,c as r,o as t,ag as s}from"./chunks/framework.dvv-DFtf.js";const f=JSON.parse('{"title":"Features Overview","description":"","frontmatter":{},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md"}'),i={name:"features/index.md"};function o(n,e,l,c,u,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="features-overview" tabindex="-1">Features Overview <a class="header-anchor" href="#features-overview" aria-label="Permalink to &quot;Features Overview&quot;">​</a></h1><p>Kubby provides a comprehensive set of features for managing Kubernetes clusters efficiently.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><h3 id="dashboard" tabindex="-1"><a href="/features/dashboard.html">Dashboard</a> <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;[Dashboard](/features/dashboard)&quot;">​</a></h3><p>Get a list of all your clusters and namespaces organized in groups in a 2D matrix.</p><h3 id="resource-list" tabindex="-1"><a href="/features/resource-list.html">Resource List</a> <a class="header-anchor" href="#resource-list" aria-label="Permalink to &quot;[Resource List](/features/resource-list)&quot;">​</a></h3><p>Browse any Kubernetes resource type with filtering, sorting, and quick actions. Works with all standard and custom resources.</p><h3 id="resource-detail" tabindex="-1"><a href="/features/resource-detail.html">Resource Detail</a> <a class="header-anchor" href="#resource-detail" aria-label="Permalink to &quot;[Resource Detail](/features/resource-detail)&quot;">​</a></h3><p>Inspect resources in detail with multiple view modes: Tree (compact hierarchical view), YAML, and JSON. Edit or copy resources directly from the detail view.</p><h3 id="log-viewer" tabindex="-1"><a href="/features/log-viewer.html">Log Viewer</a> <a class="header-anchor" href="#log-viewer" aria-label="Permalink to &quot;[Log Viewer](/features/log-viewer)&quot;">​</a></h3><p>Stream logs in real-time from pods and containers. Features syntax highlighting, formatting and auto-scroll.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><h3 id="actions" tabindex="-1"><a href="/features/actions.html">Actions</a> <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;[Actions](/features/actions)&quot;">​</a></h3><p>Perform common operations like scaling deployments, rolling restarts, editing resources, port-forward and more with single keystrokes.</p><h3 id="ai-assistant" tabindex="-1"><a href="/features/ai-assistant.html">AI Assistant</a> <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;[AI Assistant](/features/ai-assistant)&quot;">​</a></h3><p>Launch an AI coding assistant with your current Kubernetes context pre-configured. Supports Cursor, Claude Code, Augment, and Codex CLI tools.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><p>Kubby is built around these core principles:</p><ol><li><strong>Keyboard-First</strong>: Every action is accessible via keyboard shortcuts</li><li><strong>Speed</strong>: Native performance with instant feedback</li><li><strong>Simplicity</strong>: Clean interface that shows what matters</li><li><strong>Safety</strong>: Destructive actions require confirmation</li></ol>',19)])])}const p=a(i,[["render",o]]);export{f as __pageData,p as default};
